{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C14"],
      "claim": "Cerivastatin, a close statin analogue sharing the dihydroxyheptenoic acid side chain and fluorophenyl-heterocycle core, has an absolute oral bioavailability of about 60% in humans, directly supporting a high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Fluvastatin, the most similar retrieved statin, shows an oral bioavailability of 29% in healthy volunteers, above the 20% threshold and supportive of high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Rosuvastatin, another statin with the same dihydroxy acid pharmacophore, has an absolute bioavailability of about 20%, at the threshold and supportive of high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "One fluvastatin study reported 19% oral bioavailability, slightly below the threshold, indicating first-pass variability; this is a contradictory data point but is outweighed by multiple fluvastatin values of 24-30%.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a pitavastatin-like statin with the same dihydroxyheptenoic acid side chain and fluorophenyl-quinoline scaffold as the closest analogues. The most transferable statin evidence (cerivastatin ~60%, fluvastatin ~29%, rosuvastatin ~20%) consistently places oral bioavailability at or above 20%, with only one borderline fluvastatin value below threshold. Therefore the prediction is high.",
  "evidence_gaps": [
    "No direct pitavastatin bioavailability record is present in the supplied evidence.",
    "Fluvastatin values straddle the 20% threshold, and rosuvastatin sits exactly at 20%.",
    "Morgan similarities for the closest statin analogues are moderate (0.45-0.54), so transferability is not exact."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

